create view [dbo].[hes_hes_hes] as SELECT     TOP(100) PERCENT HES_K, HES_M, HES_T, HES, HES_T2, HES_T3, HES_T4, RTRIM(CAST(HES_K AS nvarchar)) + '-' + RTRIM(CAST(HES_M AS nvarchar)) + '-' + RTRIM(CAST(HES_T AS nvarchar)) + CASE WHEN HES_T2 IS NULL THEN '' ELSE '-' + RTRIM(CAST(HES_T2 AS nvarchar)) END + CASE WHEN HES_T3 IS NULL THEN '' ELSE '-' + RTRIM(CAST(HES_T3 AS nvarchar)) END AS hc, N_S, BED, BES FROM dbo.DEED_DTL WHERE     (RTRIM(CAST(HES_K AS nvarchar)) + '-' + RTRIM(CAST(HES_M AS nvarchar)) + '-' + RTRIM(CAST(HES_T AS nvarchar)) + CASE WHEN HES_T2 IS NULL THEN '' ELSE '-' + RTRIM(CAST(HES_T2 AS nvarchar)) END + CASE WHEN HES_T3 IS NULL THEN '' ELSE '-' + RTRIM(CAST(HES_T3 AS nvarchar)) END <> HES) ORDER BY HES_K 
